# ---------------------------------------------------------------- quad
def qc(name: str, got, err_rtol: float = 1e-3):
    ref = QUAD[name]
    check(name, close(got[0], ref[0], 1e-13, 1e-15))
    check(name + ' err', close(got[1], ref[1], err_rtol, 1e-300))

qc('poly', I.quad(lambda x: x*x, 0, 4))
qc('expinf', I.quad(lambda x: math.exp(-x), 0, np.inf))
qc('gauss', I.quad(lambda x: math.exp(-x*x), -np.inf, np.inf))
qc('sqrt', I.quad(lambda x: 1/math.sqrt(x), 0, 1), 1.0)
qc('log', I.quad(lambda x: math.log(x), 0, 1), 1.0)
qc('args', I.quad(lambda x, a: math.sin(a*x), 0, 3, args=(2.0,)))
qc('points', I.quad(lambda x: abs(x-0.3), 0, 1, points=[0.3]))
qc('points2', I.quad(lambda x: 1.0 if x < 0.5 else 2.0, 0, 2, points=[0.5, 1.7, 5.0]), 1.0)
qc('neginf', I.quad(lambda x: 1/(1+x*x), -np.inf, 0))
qc('flip', I.quad(lambda x: x**3, 2, -1), 1.0)
qc('limit3', I.quad(lambda x: math.cos(50*x), 0, 1, limit=3))
qc('tol', I.quad(lambda x: math.exp(x), 0, 1, epsabs=1e-3, epsrel=1e-3), 1.0)
qc('dbl', I.dblquad(lambda y, x: x*y, 0, 2, 0, 1), 1.0)
qc('dblf', I.dblquad(lambda y, x: x*y, 0, 1, lambda x: 0.0, lambda x: 1-2*x), 1.0)
qc('dbla', I.dblquad(lambda y, x, k: k*x + y, 0, 1, 0, 2, args=(3.0,)), 1.0)
qc('tpl', I.tplquad(lambda z, y, x: x*y*z, 0, 1, 0, 2, 0, 3), 1.0)
qc('tplf', I.tplquad(lambda z, y, x: x + y + z, 0, 1, lambda x: 0.0, lambda x: x,
                     lambda x, y: 0.0, lambda x, y: x*y), 1.0)
check('quad a==b', I.quad(lambda x: x, 1.0, 1.0) == (0.0, 0.0))
for kw in range(3):
    raised = False
    try:
        if kw == 0:
            I.quad(lambda x: x, 0, 1, limit=0)
        elif kw == 1:
            I.quad(lambda x: x, 0, 1, epsabs=0.0, epsrel=1e-30)
        else:
            I.quad(lambda x: x, 0, np.inf, points=[1.0])
    except ValueError:
        raised = True
    check('quad raises ' + str(kw), raised)

