for k in range(4):
    raised = False
    try:
        if k == 0:
            I.romb(r[:6])
        elif k == 1:
            I.cumulative_trapezoid(y, initial=1.0)
        elif k == 2:
            I.cumulative_simpson(y, x=x[::-1])
        else:
            I.trapezoid(y, x[:3])
    except ValueError:
        raised = True
    check('sampled raises ' + str(k), raised)

